operations.new_template:
const mainStories = __MAIN_STORIES__;
function mainItem(s){
  const cfg=phase(s),item=clone(ShrineTemplates['绘马板.绘马']);
  const story=mainStories.find(x=>x.编号===cfg.mainId);
  assert(story,'本章主线故事配置缺失');
  Object.assign(item,clone(story),{标题:ShrineConfig.mainTitles[cfg.level-1],补充说明:story.补充说明+' 主线绘马。完成本章还需'+cfg.facility+'修缮至4；可以先调查或先建设。',材料档:cfg.level,性质:'主线',状态:'未接'});
  return item;
}
